package br.com.confirmacao.professional.location.application;
import br.com.confirmacao.professional.application.ProfessionalNotFoundException;import br.com.confirmacao.professional.infrastructure.ProfessionalRepository;import br.com.confirmacao.professional.location.domain.ProfessionalLocation;import br.com.confirmacao.professional.location.infrastructure.ProfessionalLocationRepository;import jakarta.persistence.EntityManager;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.UUID;
@Service public class ProfessionalLocationService{private final ProfessionalLocationRepository locations;private final ProfessionalRepository professionals;private final EntityManager entityManager;public ProfessionalLocationService(ProfessionalLocationRepository l,ProfessionalRepository p,EntityManager e){locations=l;professionals=p;entityManager=e;}@Transactional(readOnly=true)public ProfessionalLocation find(UUID id){var professional=professionals.findById(id).orElseThrow(()->new ProfessionalNotFoundException(id));return locations.findById(id).orElseGet(()->new ProfessionalLocation(id,"Não informado","",professional.getTimezone()));}@Transactional public ProfessionalLocation save(UUID id,String city,String state,String timezone){professionals.findById(id).orElseThrow(()->new ProfessionalNotFoundException(id));var location=locations.findById(id).orElseGet(()->new ProfessionalLocation(id,city,state,timezone));location.update(city,state,timezone);entityManager.createNativeQuery("UPDATE professionals SET timezone=:timezone,updated_at=CURRENT_TIMESTAMP WHERE id=:id").setParameter("timezone",timezone.trim()).setParameter("id",id).executeUpdate();return locations.save(location);}}
